def total_rubric_points():
    return sum(r["total"] for r in RUBRICS)


def assignment_points():
    return sum(a["points"] for a in ASSIGNMENTS)


def verify():
    """Raise on inconsistencies; returns a list of info strings."""
    problems = []
    total = total_rubric_points()
    if total != COURSE["total_points"]:
        problems.append("rubric total %d != %d" % (total, COURSE["total_points"]))
    if len(WEEKS) != 16:
        problems.append("expected 16 weeks, got %d" % len(WEEKS))
    if len(RUBRICS) != 10:
        problems.append("expected 10 rubrics, got %d" % len(RUBRICS))
    week_slugs = {r["slug"] for r in RUBRICS}
    for a in ASSIGNMENTS:
        if ("rubric", a["slug"]) not in [it for _m, its in MODULES for it in its]:
            problems.append("assignment %s has no rubric in MODULES" % a["slug"])
    seen = set()
    for _title, items in MODULES:
        for it in items:
            if it in seen:
                problems.append("duplicate module item %r" % (it,))
            seen.add(it)
    if problems:
        raise ValueError("; ".join(problems))
    return ["rubric points: %d/%d" % (total, COURSE["total_points"]),
            "weeks: %d, rubrics: %d, assignments: %d, discussions: %d"
            % (len(WEEKS), len(RUBRICS), len(ASSIGNMENTS), len(DISCUSSIONS))]
